#!/usr/bin/env bash
# Створює issues для карток дошки. Потрібен gh (GitHub CLI) і вхід: gh auth login
# Запуск з кореня репозиторію: bash scripts/create-issues.sh
set -e
gh issue create --title "T1: Створити модуль Storage Adapter: load()/save() з try/catch навколо localStorage" --body "$(printf 'Story: SP-09\nКритерій завершення: Усі читання й запис localStorage йдуть через адаптер; збій не зупиняє застосунок\nОцінка: 2,0 год\nЗалежності: —\nВласник: Ніка')"
gh issue create --title "T2: Додати перевірку схеми JSON (масив; id, title — рядки; done — boolean); пошкоджений рядок зберегти в ключі studyplanner.tasks.v1.backup" --body "$(printf 'Story: SP-09\nКритерій завершення: Некоректний JSON → порожній список і повідомлення (TC-08)\nОцінка: 1,0 год\nЗалежності: T1\nВласник: Ніка')"
gh issue create --title "T3: Показати банер помилки запису з кнопкою «Спробувати ще раз»; стан списку при збої не змінювати" --body "$(printf 'Story: SP-09\nКритерій завершення: Імітований збій запису → банер, список без змін (TC-07)\nОцінка: 1,5 год\nЗалежності: T1\nВласник: Ніка')"
gh issue create --title "T4: Перевірити TC-07 і TC-08, записати результат у docs/test-cases.md" --body "$(printf 'Story: SP-09\nКритерій завершення: TC-07 і TC-08 мають статус «пройдено» з датою\nОцінка: 1,0 год\nЗалежності: T2, T3\nВласник: Ніка')"
gh issue create --title "T5: Реалізувати модальне підтвердження видалення («Видалити» / «Скасувати», Esc, повернення фокуса)" --body "$(printf 'Story: SP-08\nКритерій завершення: Після «Скасувати» запис лишається, після підтвердження зникає\nОцінка: 2,0 год\nЗалежності: —\nВласник: Ніка')"
gh issue create --title "T6: Перевірити TC-09 і зафіксувати результат" --body "$(printf 'Story: SP-08\nКритерій завершення: TC-09 пройдено\nОцінка: 0,5 год\nЗалежності: T5\nВласник: Ніка')"
gh issue create --title "T7: Додати функцію форматування дати дд.мм.рррр без зсуву часової зони" --body "$(printf 'Story: SP-10\nКритерій завершення: 2026-11-18 відображається як 18.11.2026\nОцінка: 1,0 год\nЗалежності: —\nВласник: Ніка')"
gh issue create --title "T8: Додати позначку «Прострочено» (текст + стиль) для невиконаних завдань із минулим дедлайном" --body "$(printf 'Story: SP-10\nКритерій завершення: Учорашній дедлайн → «Прострочено»; сьогоднішній і виконані — ні\nОцінка: 1,0 год\nЗалежності: T7\nВласник: Ніка')"
gh issue create --title "T9: Перевірити TC-10 і зафіксувати результат" --body "$(printf 'Story: SP-10\nКритерій завершення: TC-10 пройдено\nОцінка: 0,5 год\nЗалежності: T8\nВласник: Ніка')"
gh issue create --title "T10: Додати валідацію назви: trim(), 1–100 символів, повідомлення біля поля" --body "$(printf 'Story: SP-11\nКритерій завершення: Порожня назва або 101 символ — завдання не додається, видно правило\nОцінка: 1,0 год\nЗалежності: —\nВласник: Ніка')"
gh issue create --title "T11: Перевірити TC-11 і зафіксувати результат" --body "$(printf 'Story: SP-11\nКритерій завершення: TC-11 пройдено\nОцінка: 0,5 год\nЗалежності: T10\nВласник: Ніка')"
gh issue create --title "T12: Уточнити README: редагування поза межами MVP, посилання на docs і запуск" --body "$(printf 'Story: SP-14\nКритерій завершення: README не суперечить статуту та журналу рішень\nОцінка: 0,5 год\nЗалежності: —\nВласник: Ніка')"
gh issue create --title "T13: Регресійна перевірка TC-01–TC-06 після всіх змін" --body "$(printf 'Story: SP-06\nКритерій завершення: TC-01–TC-06 пройдено; основний сценарій ≤ 2 хв\nОцінка: 1,0 год\nЗалежності: T4, T6, T9, T11\nВласник: Ніка')"
gh issue create --title "T14: Оновити backlog, test-cases, decision-log; підготувати розділ «Що змінено після review»" --body "$(printf 'Story: —\nКритерій завершення: Документи в docs/ відповідають стану коду й дошки\nОцінка: 1,0 год\nЗалежності: T12, T13\nВласник: Ніка')"
gh issue create --title "T15: Контрольна перевірка темпу й ризиків 25.11: оновити реєстр, за потреби скоротити обсяг" --body "$(printf 'Story: —\nКритерій завершення: Реєстр ризиків оновлено, рішення записано в журнал\nОцінка: 0,5 год\nЗалежності: T4\nВласник: Ніка')"
gh issue create --title "S1: Стретч: коректне відмінювання лічильника (1 завдання / 2 завдання / 5 завдань)" --body "$(printf 'Story: SP-12\nКритерій завершення: Правильна форма для 1, 2, 5, 11, 21\nОцінка: 1,0 год\nЗалежності: —\nВласник: Ніка')"
